+export function remaining(state, id) {
+  const slot = state.slots.find(slot => slot.id === id);
+  if (!slot) throw new Error('없는 수업');
+  return slot.capacity - slot.booked;
+}
+
+export function book(state, request) {
+  const { slotId, name, seats } = request;
+  if (typeof name !== 'string' || !name.trim()) {
+    throw new Error('이름을 입력하세요');
+  }
+  if (!Number.isInteger(seats) || seats <= 0) {
+    throw new Error('좌석 수는 숫자형 양의 정수여야 합니다');
+  }
+  if (seats > remaining(state, slotId)) {
+    throw new Error('잔여 좌석이 부족합니다');
+  }
+
+  return {
+    ...state,
+    slots: state.slots.map(slot => slot.id === slotId
+      ? { ...slot, booked: slot.booked + seats }
+      : slot),
+    reservations: [
+      ...state.reservations,
+      { slotId, name: name.trim(), seats },
+    ],
+  };
+}
