+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { book, remaining } from '../src/booking.mjs';
+
+function makeState() {
+  return {
+    slots: [
+      { id: 'clay', capacity: 3, booked: 1 },
+      { id: 'wood', capacity: 5, booked: 2 },
+    ],
+    reservations: [{ slotId: 'clay', name: '기존 손님', seats: 1 }],
+  };
+}
+
+function freezeDeep(value) {
+  for (const child of Object.values(value)) {
+    if (child && typeof child === 'object') freezeDeep(child);
+  }
+  return Object.freeze(value);
+}
+
+function assertRejected(request, message, state = makeState()) {
+  const before = structuredClone(state);
+  freezeDeep(state);
+  assert.throws(() => book(state, request), message);
+  assert.deepEqual(state, before);
+}
+
+test('잔여 좌석 조회', () => {
+  assert.equal(remaining(makeState(), 'clay'), 2);
+});
+
+test('없는 수업의 잔여 조회는 오류', () => {
+  assert.throws(() => remaining(makeState(), 'missing'), /없는 수업/);
+});
+
+test('확인표 없이 바로 예약하고 이름을 정리하며 입력 state와 요청을 보존', () => {
+  const state = makeState();
+  const before = structuredClone(state);
+  freezeDeep(state);
+  const request = Object.freeze({ slotId: 'clay', name: '  김 손님 \t', seats: 2 });
+
+  const result = book(state, request);
+
+  assert.deepEqual(result, {
+    slots: [
+      { id: 'clay', capacity: 3, booked: 3 },
+      { id: 'wood', capacity: 5, booked: 2 },
+    ],
+    reservations: [
+      { slotId: 'clay', name: '기존 손님', seats: 1 },
+      { slotId: 'clay', name: '김 손님', seats: 2 },
+    ],
+  });
+  assert.notEqual(result, state);
+  assert.notEqual(result.slots, state.slots);
+  assert.notEqual(result.slots[0], state.slots[0]);
+  assert.notEqual(result.reservations, state.reservations);
+  assert.notEqual(result.reservations.at(-1), request);
+  assert.deepEqual(state, before);
+  assert.equal(request.name, '  김 손님 \t');
+  assert.equal(remaining(result, 'clay'), 0);
+});
+
+test('연속 예약은 반환된 state의 잔여를 반영하고 만석이면 거부', () => {
+  const original = freezeDeep(makeState());
+  const first = book(original, { slotId: 'clay', name: '첫 손님', seats: 1 });
+  freezeDeep(first);
+  const second = book(first, { slotId: 'clay', name: '둘째 손님', seats: 1 });
+  assert.equal(remaining(original, 'clay'), 2);
+  assert.equal(remaining(first, 'clay'), 1);
+  assert.equal(remaining(second, 'clay'), 0);
+  assert.equal(second.reservations.length, 3);
+  assertRejected({ slotId: 'clay', name: '추가 손님', seats: 1 }, /잔여 좌석/, second);
+});
+
+test('없는 수업 예약은 입력 보존 후 오류', () => {
+  assertRejected({ slotId: 'missing', name: '손님', seats: 1 }, /없는 수업/);
+});
+
+test('잔여보다 많은 예약은 입력 보존 후 오류', () => {
+  assertRejected({ slotId: 'clay', name: '손님', seats: 3 }, /잔여 좌석/);
+});
+
+for (const [label, name] of [
+  ['빈 문자열', ''],
+  ['공백만 있는 문자열', ' \t\n '],
+  ['null', null],
+  ['숫자', 123],
+]) {
+  test(`잘못된 이름(${label})은 입력 보존 후 오류`, () => {
+    assertRejected({ slotId: 'clay', name, seats: 1 }, /이름/);
+  });
+}
+
+for (const [label, seats] of [
+  ['0', 0],
+  ['음수', -1],
+  ['소수', 1.5],
+  ['숫자 문자열', '1'],
+  ['NaN', NaN],
+  ['Infinity', Infinity],
+  ['누락', undefined],
+  ['null', null],
+  ['불리언', true],
+]) {
+  test(`잘못된 좌석 수(${label})는 입력 보존 후 오류`, () => {
+    assertRejected({ slotId: 'clay', name: '손님', seats }, /숫자형 양의 정수/);
+  });
+}

