+  }
+
+  const [year, month, day] = value.split('-').map(Number);
+  const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
+  const daysInMonth = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
+  if (year < 1 || month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
+    throw invalid();
+  }
+}
+
+export function summarize(rows, asOf) {
+  assertCalendarDate(asOf, 'asOf');
+  const summary = { total: rows.length, returned: 0, open: 0, overdue: 0 };
+
+  for (const [index, row] of rows.entries()) {
+    if (row.status !== 'loaned' && row.status !== 'returned') {
+      throw new TypeError(`rows[${index}].status must be loaned or returned`);
+    }
+    assertCalendarDate(row.dueDate, `rows[${index}].dueDate`);
+
+    if (row.status === 'returned') {
+      summary.returned += 1;
+    } else {
+      summary.open += 1;
+      if (row.dueDate < asOf) summary.overdue += 1;
+    }
+  }
+
