+function validateDate(value, field) {
+  if (typeof value !== 'string' || value.length !== 10 || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
+    throw new TypeError(`${field} must be a valid YYYY-MM-DD date`);
+  }
+
+  const [year, month, day] = value.split('-').map(Number);
+  const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
+  const monthDays = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
+  if (month < 1 || month > 12 || day < 1 || day > monthDays[month - 1]) {
+    throw new RangeError(`${field} must be a valid YYYY-MM-DD date`);
+  }
+}
+
+export function summarize(rows, asOf) {
+  validateDate(asOf, 'asOf');
+  const result = { total: rows.length, returned: 0, open: 0, overdue: 0 };
+
+  for (const [index, row] of rows.entries()) {
+    if (row?.status !== 'loaned' && row?.status !== 'returned') {
+      throw new TypeError(`rows[${index}].status must be loaned or returned`);
+    }
+    validateDate(row.dueDate, `rows[${index}].dueDate`);
+
+    if (row.status === 'returned') {
+      result.returned += 1;
+    } else {
+      result.open += 1;
+      // Validated, fixed-width dates compare chronologically without timezone conversion.
+      if (row.dueDate < asOf) result.overdue += 1;
+    }
+  }
+
+  return result;
+}
